/**
 * Visible-light (ROYGBIV, 380-700 nm) emission spectral line data.
 *
 * Source: NIST Atomic Spectra Database (ASD) export supplied by the project
 * owner, filtered to the human-visible range (380-700 nm). For each element
 * the raw line list is reduced for a clean classroom strip: near-duplicate
 * wavelengths are merged (observed preferred over Ritz-calculated), lines
 * sharing the same rendered color are compressed to their strongest
 * representative, the weakest lines (below ~1.5% of the element's peak) are
 * dropped, and each element is capped at its 25 strongest lines. Relative
 * intensities are sqrt-scaled to 0-1 per element for display opacity.
 *
 * This file is generated from the ASD export: do not hand-edit line data;
 * re-run the generator to refresh. Covers 97 elements; Astatine (not in the
 * source) and Francium (no listed intensities) have no data and fall back to
 * the "no lines on record" message, as do synthetic elements beyond Z=99.
 */

export interface SpectralLine {
  wavelength: number; // nm
  intensity?: number; // relative 0-1, omit = 1
}

