/** Returns the visible-range emission lines for a given atomic number, or an empty array if unknown. */
export const getEmissionLines = (atomicNumber: number): SpectralLine[] =>
  EMISSION_LINES[atomicNumber] ?? [];

/**
 * Approximates the perceived RGB color of a visible wavelength (380-700 nm)
 * using Dan Bruton's classic visible-spectrum algorithm, including intensity
 * falloff near the violet and red edges of human vision.
 */
export const wavelengthToColor = (nm: number): string => {
  let r = 0;
  let g = 0;
  let b = 0;

  if (nm >= 380 && nm < 440) {
    r = -(nm - 440) / (440 - 380);
    g = 0;
    b = 1;
  } else if (nm >= 440 && nm < 490) {
    r = 0;
    g = (nm - 440) / (490 - 440);
    b = 1;
  } else if (nm >= 490 && nm < 510) {
    r = 0;
    g = 1;
    b = -(nm - 510) / (510 - 490);
  } else if (nm >= 510 && nm < 580) {
    r = (nm - 510) / (580 - 510);
    g = 1;
    b = 0;
  } else if (nm >= 580 && nm < 645) {
    r = 1;
    g = -(nm - 645) / (645 - 580);
    b = 0;
  } else if (nm >= 645 && nm <= 700) {
    r = 1;
    g = 0;
    b = 0;
  }

  // Intensity falloff near the edges of visibility
  let factor = 1.0;
  if (nm >= 380 && nm < 420) {
    factor = 0.3 + (0.7 * (nm - 380)) / (420 - 380);
  } else if (nm >= 420 && nm < 701) {
    factor = 1.0;
  } else if (nm >= 701 && nm <= 780) {
    factor = 0.3 + (0.7 * (780 - nm)) / (780 - 700);
  } else {
    factor = 0.0;
  }

  const gamma = 0.8;
  const adjust = (c: number): number => (c === 0 ? 0 : Math.round(255 * Math.pow(c * factor, gamma)));

  return `rgb(${adjust(r)}, ${adjust(g)}, ${adjust(b)})`;
};
